options.afterRender:
(() => {
  const HOST = '/cpms';
  const KEY = 'chiller.staging_load_source';
  const VALID_VALUES = ['HEADER', 'CHILLER_ESTIMATED'];
  const panel = document.getElementById('chillerStagingLoadSource');
  if (!panel) return;

  const fieldset = panel.querySelector('.staging-source-options');
  const inputs = [...panel.querySelectorAll('input[name="chiller-staging-load-source"]')];
  const cancelButton = panel.querySelector('.cancel');
  const saveButton = panel.querySelector('.save');
  const message = panel.querySelector('.staging-source-message');
  const rows = typeof context !== 'undefined' && Array.isArray(context.data) ? context.data[0] : [];
  const parameter = rows.find((row) => row?.key === KEY);
  let currentValue = parameter?.value;
  let busy = false;

  const selectedValue = () => inputs.find((input) => input.checked)?.value;

  const setMessage = (text, isError = false) => {
    message.textContent = text;
    message.classList.toggle('error', isError);
  };

  const selectValue = (value) => {
    inputs.forEach((input) => {
      input.checked = input.value === value;
    });
  };

  const render = () => {
    const ready = VALID_VALUES.includes(currentValue);
    const changed = selectedValue() !== currentValue;
    fieldset.disabled = busy || !ready;
    cancelButton.disabled = busy || !ready || !changed;
    saveButton.disabled = busy || !ready || !changed;
  };

  const responseBody = async (response) => {
    const text = await response.text();
    if (!text) return undefined;
    try {
      return JSON.parse(text);
    } catch {
      return text;
    }
  };

  const errorMessage = (body, response) =>
    typeof body === 'string' ? body : body?.error || body?.message || `HTTP ${response.status}`;

  inputs.forEach((input) => input.addEventListener('change', render));

  cancelButton.addEventListener('click', () => {
    selectValue(currentValue);
    setMessage(`Current source: ${currentValue === 'HEADER' ? 'Plant Header' : 'Chiller Estimated'}`);
    render();
  });

  saveButton.addEventListener('click', async () => {
    const value = selectedValue();
    if (!VALID_VALUES.includes(value) || value === currentValue) return;

    let reason = '';
    while (!reason) {
      const input = window.prompt('Remark for this change:', reason);
      if (input === null) return;
      reason = input.trim();
      if (!reason) window.alert('Remark is required.');
    }

    const label = value === 'HEADER' ? 'Plant Header' : 'Chiller Estimated';
    if (!window.confirm(`Use ${label} for automatic chiller staging?`)) return;

    busy = true;
    setMessage('Saving...');
    render();

    try {
      const response = await fetch(`${HOST}/params/value`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          scope: parameter.scope,
          equipmentKind: parameter.equipment_kind,
          equipmentId: parameter.equipment_id,
          key: KEY,
          value,
          reason,
        }),
      });
      const body = await responseBody(response);
      if (!response.ok) throw new Error(errorMessage(body, response));

      currentValue = value;
      setMessage(`Current source: ${label}`);
      if (typeof context !== 'undefined' && context.grafana?.refresh) context.grafana.refresh();
    } catch (error) {
      selectValue(currentValue);
      setMessage(`Unable to save parameter: ${error.message}`, true);
    } finally {
      busy = false;
      render();
    }
  });

  if (VALID_VALUES.includes(currentValue)) {
    selectValue(currentValue);
    setMessage(`Current source: ${currentValue === 'HEADER' ? 'Plant Header' : 'Chiller Estimated'}`);
  } else {
    console.log(`Invalid or missing ${KEY} query result`, true);
    selectValue('HEADER');
  }
  render();
})();

