options.afterRender:
(() => {
  const HOST = '/cpms';
  const KEY = 'ct_fan.cws_controller';
  const panel = document.getElementById('ctFanCwsOutdoorTargets');
  if (!panel) return;

  const tbody = panel.querySelector('tbody');
  const settingsPanel = panel.querySelector('.outdoor-targets-settings');
  const controllerInputs = [...panel.querySelectorAll('.controller-field')];
  const addButton = panel.querySelector('.add');
  const cancelButton = panel.querySelector('.cancel');
  const saveButton = panel.querySelector('.save');
  const message = panel.querySelector('.outdoor-targets-message');
  const frames = typeof context !== 'undefined' && Array.isArray(context.data) ? context.data : [];
  const rows = Array.isArray(frames[0]) ? frames[0] : frames;
  const parameter = rows.find((row) => row?.key === KEY);

  const parseController = (value) => {
    if (value && typeof value === 'object' && !Array.isArray(value)) return value;
    if (typeof value !== 'string') return undefined;
    try {
      const parsed = JSON.parse(value);
      return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : undefined;
    } catch {
      return undefined;
    }
  };

  let controller = parseController(parameter?.value);
  let settings = {};
  let ranges = [];
  let busy = false;

  const copySettings = (value) => ({
    enabled: value?.enabled !== false,
    defaultHz: Number(value?.defaultHz),
    minHz: Number(value?.minHz),
    maxHz: Number(value?.maxHz),
    stepHz: Number(value?.stepHz),
    target: Number(value?.target),
    deadband: Number(value?.deadband),
    holdMs: Number(value?.holdMs),
    dwellMs: Number(value?.dwellMs),
  });

  const copyRanges = (value) =>
    Array.isArray(value)
      ? value.map(({ min, max, target }) => ({ min: Number(min), max: Number(max), target: Number(target) }))
      : [];

  const normalized = (value) =>
    value
      .map(({ min, max, target }) => ({ min: Number(min), max: Number(max), target: Number(target) }))
      .sort((a, b) => a.min - b.min || a.max - b.max);

  const setMessage = (text, isError = false) => {
    message.textContent = text;
    message.classList.toggle('error', isError);
  };

  const validationError = () => {
    const numericSettings = [
      settings.defaultHz,
      settings.minHz,
      settings.maxHz,
      settings.stepHz,
      settings.target,
      settings.deadband,
      settings.holdMs,
      settings.dwellMs,
    ];
    if (numericSettings.some((value) => !Number.isFinite(value))) return 'Every controller setting requires a numeric value.';
    if (settings.minHz >= settings.maxHz) return 'Minimum speed must be lower than maximum speed.';
    if (settings.defaultHz < settings.minHz || settings.defaultHz > settings.maxHz) {
      return 'Fixed speed must be within the configured speed range.';
    }
    if (settings.stepHz <= 0) return 'Speed step must be greater than zero.';
    if (settings.deadband < 0) return 'Deadband cannot be negative.';
    if (settings.holdMs < 0 || settings.dwellMs < 0) return 'Hold and dwell cannot be negative.';

    const sorted = normalized(ranges);
    if (sorted.some((range) => !Number.isFinite(range.min) || !Number.isFinite(range.max) || !Number.isFinite(range.target))) {
      return 'Every range requires numeric minimum, maximum, and target values.';
    }
    if (sorted.some((range) => range.min >= range.max)) return 'Each minimum must be lower than its maximum.';
    if (sorted.some((range, index) => index > 0 && range.min < sorted[index - 1].max)) {
      return 'Outdoor temperature ranges cannot overlap.';
    }
    return '';
  };

  const isChanged = () => {
    const current = { ...settings, targetByOutdoorTemp: normalized(ranges) };
    const original = {
      ...copySettings(controller),
      targetByOutdoorTemp: normalized(copyRanges(controller?.targetByOutdoorTemp)),
    };
    return JSON.stringify(current) !== JSON.stringify(original);
  };

  const renderSettings = () => {
    controllerInputs.forEach((input) => {
      const value = settings[input.dataset.field];
      if (input.type === 'checkbox') {
        input.checked = Boolean(value);
      } else {
        const scale = Number(input.dataset.scale ?? 1);
        input.value = Number.isFinite(value) ? value / scale : '';
      }
    });
  };

  const renderRows = () => {
    tbody.innerHTML = '';
    if (ranges.length === 0) {
      const row = document.createElement('tr');
      row.innerHTML = '<td class="outdoor-targets-empty" colspan="4">No outdoor temperature ranges configured.</td>';
      tbody.appendChild(row);
      return;
    }

    ranges.forEach((range, index) => {
      const row = document.createElement('tr');
      row.innerHTML = `
        <td><div class="outdoor-targets-input-wrap"><input class="outdoor-targets-input" data-index="${index}" data-field="min" type="number" step="0.1" value="${range.min}"><span class="outdoor-targets-unit">&deg;C</span></div></td>
        <td><div class="outdoor-targets-input-wrap"><input class="outdoor-targets-input" data-index="${index}" data-field="max" type="number" step="0.1" value="${range.max}"><span class="outdoor-targets-unit">&deg;C</span></div></td>
        <td><div class="outdoor-targets-input-wrap"><input class="outdoor-targets-input" data-index="${index}" data-field="target" type="number" step="0.1" value="${range.target}"><span class="outdoor-targets-unit">&deg;C</span></div></td>
        <td><button class="outdoor-targets-action delete" data-index="${index}" type="button" title="Delete range" aria-label="Delete range">&#10005;</button></td>
      `;
      tbody.appendChild(row);
    });
  };

  const renderState = () => {
    const ready = Boolean(controller && parameter);
    const error = ready ? validationError() : '';
    const changed = ready && isChanged();
    panel.querySelectorAll('.controller-field, .outdoor-targets-table .outdoor-targets-input, .delete').forEach((element) => {
      element.disabled = busy || !ready;
    });
    addButton.disabled = busy || !ready;
    cancelButton.disabled = busy || !changed;
    saveButton.disabled = busy || !changed || Boolean(error);
    if (!busy && error) setMessage(error, true);
    if (!busy && !error && ready) {
      setMessage(settings.enabled ? 'Automatic CWS temperature control enabled.' : 'Fixed fan speed control enabled.');
    }
  };

  const render = () => {
    renderSettings();
    renderRows();
    renderState();
  };

  const responseBody = async (response) => {
    const text = await response.text();
    if (!text) return undefined;
    try {
      return JSON.parse(text);
    } catch {
      return text;
    }
  };

  const errorMessage = (body, response) =>
    typeof body === 'string' ? body : body?.error || body?.message || `HTTP ${response.status}`;

  const bindEvent = (element, eventName, handler) => {
    const handlers = element.__outdoorTargetHandlers ?? {};
    if (handlers[eventName]) element.removeEventListener(eventName, handlers[eventName]);
    handlers[eventName] = handler;
    element.__outdoorTargetHandlers = handlers;
    element.addEventListener(eventName, handler);
  };

  bindEvent(settingsPanel, 'input', (event) => {
    const input = event.target.closest('.controller-field');
    if (!input) return;
    if (input.type === 'checkbox') {
      settings[input.dataset.field] = input.checked;
    } else {
      const scale = Number(input.dataset.scale ?? 1);
      settings[input.dataset.field] = input.value === '' ? NaN : Number(input.value) * scale;
    }
    renderState();
  });

  bindEvent(tbody, 'input', (event) => {
    const input = event.target.closest('.outdoor-targets-input');
    if (!input) return;
    ranges[Number(input.dataset.index)][input.dataset.field] = input.value === '' ? NaN : Number(input.value);
    renderState();
  });

  bindEvent(tbody, 'click', (event) => {
    const button = event.target.closest('.delete');
    if (!button || busy) return;
    ranges.splice(Number(button.dataset.index), 1);
    render();
  });

  bindEvent(addButton, 'click', () => {
    const sorted = normalized(ranges);
    const min = sorted.length > 0 && Number.isFinite(sorted.at(-1).max) ? sorted.at(-1).max : 25;
    ranges.push({ min, max: min + 1, target: Number(settings.target) });
    render();
    tbody.querySelector(`input[data-index="${ranges.length - 1}"]`)?.focus();
  });

  bindEvent(cancelButton, 'click', () => {
    settings = copySettings(controller);
    ranges = copyRanges(controller.targetByOutdoorTemp);
    render();
  });

  bindEvent(saveButton, 'click', async () => {
    const error = validationError();
    if (error || !isChanged()) return;

    let reason = '';
    while (!reason) {
      const input = window.prompt(
        'Confirm saving cooling tower fan CWS controller settings.\n\nEnter a remark for this change:',
        reason,
      );
      if (input === null) return;
      reason = input.trim();
      if (!reason) window.alert('Remark is required.');
    }

    const nextRanges = normalized(ranges);

    busy = true;
    setMessage('Saving...');
    renderState();

    try {
      const nextController = { ...controller, ...settings, targetByOutdoorTemp: nextRanges };
      const response = await fetch(`${HOST}/params/value`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          scope: parameter.scope,
          equipmentKind: parameter.equipment_kind,
          equipmentId: parameter.equipment_id,
          key: KEY,
          value: nextController,
          reason,
        }),
      });
      const body = await responseBody(response);
      if (!response.ok) throw new Error(errorMessage(body, response));

      controller = nextController;
      settings = copySettings(nextController);
      ranges = copyRanges(nextRanges);
      setMessage('Controller settings saved.');
      if (typeof context !== 'undefined' && context.grafana?.refresh) context.grafana.refresh();
    } catch (error) {
      setMessage(`Unable to save parameter: ${error.message}`, true);
    } finally {
      busy = false;
      renderState();
    }
  });

  if (controller && parameter) {
    settings = copySettings(controller);
    ranges = copyRanges(controller.targetByOutdoorTemp);
    render();
  } else {
    setMessage(`Invalid or missing ${KEY} query result`, true);
    render();
  }
})();

